// === Tab: mySketch ===
let lineGeom
let wobble

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)

	lineGeom = buildGeometry(() => {
		noFill()
		beginShape()
		const n = 400
		for (let i = 0; i <= n; i++) {
			vertex(
				map(i, 0, n, -width/2, width/2),
				0
			)
		}
		endShape()
	})

	wobble = baseStrokeShader().modify(() => {
		const t = uniformFloat(() => millis())
		const size = uniformVec2(() => [width, height])
		const falloff = uniformFloat(() => map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.8, 0, true))
		const spread = uniformFloat(() => map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 1, true))
		getWorldInputs((inputs) => {
			noiseDetail(3, falloff)
			const progress = instanceID() / 50
			inputs.position.y += (noise(inputs.position.x / size.x * 3, t * 0.0001, progress*0.09*spread)) *
				size.y * 0.5
			let c = [1, 1, 1, 1]
			if (progress < 0.5) {
				c = mix(
					[1, 0, 0, 1],
					[0, 1, 0, 1],
					progress * 2
				)
			} else {
				c = mix(
					[0, 1, 0, 1],
					[0, 0, 1, 1],
					(progress - 0.5) * 2
				)
			}
			c.a = 1 / 20
			inputs.color = c
			return inputs
		})
	})
}

function draw() {
	background('#3B2280')
	push()
	strokeWeight(5)
	strokeShader(wobble)
	blendMode(ADD)
	model(lineGeom, 50)
	pop()
}

